INSERT INTO `battle_pay_entry_locale` (`ID`, `Locale`, `Title`, `Description`) VALUES
(1, "esMX", "|cffff8000Promoción", "Posibilidad de \"promocionar\" tu personaje en la cuenta actual o crear uno nuevo con algunos bonos.\n\nComo bonos recibirás:\n- Equipamiento de nivel de objeto 408\n- Arma de nivel de objeto 408\n- Accesorios y capa de nivel de objeto 408\n- 1.000 de oro\n- Nivel 90 instantáneo\n- Montura: Rienda de viento anaranjado (Horda) o Grifo blanco (Alianza)"),
(2, "esMX", "|cffff8000Promoción", "Posibilidad de \"promocionar\" tu personaje en la cuenta actual o crear uno nuevo con algunos bonos.\n\nComo bonos recibirás:\n- Equipamiento de nivel de objeto 408\n- Arma de nivel de objeto 408\n- Accesorios y capa de nivel de objeto 408\n- 1.000 de oro\n- Nivel 90 instantáneo\n- Montura: Rienda de viento anaranjado (Horda) o Grifo blanco (Alianza)"),
